6	/* GuideJar embed wrapper */
7	.guidejarWrapper {
8	  position: relative;
9	  height: 0;
10	  width: 100%;
11	  overflow: hidden;
12	  z-index: var(--z-nav);
13	  border-radius: 10px;
14	  box-sizing: border-box;
15	  padding-bottom: calc(56.25% + 32px);
16	}
17	
18	/* GuideJar iframe — fills the wrapper */
19	.guidejarIframe {
20	  position: absolute;
21	  inset: 0;
22	}
23	
24	/* Typewriter span container */
25	.typewriterContainer {
26	  display: inline-block;
27	  min-width: 280px;
28	  text-align: left;
29	  vertical-align: baseline;
30	  /* Explicit fallback color so accessibility audits read correct contrast ratio.
31	     Visually the child .animate-span overrides this with #019ae6. */
32	  color: #019ae6;
33	}
34	
35	/* Typewriter animated word */
36	.typewriterWord {
37	  display: inline-block;
38	  /* Explicit fallback so motion.span inherits readable color in audit contexts. */
39	  color: #019ae6;
40	}
